function containsDuplicate(arr) {
  const seen = new Set(); // O(n) in time, O(n) in space
  for (const x of arr) {
    if (seen.has(x)) return true;
    seen.add(x);
  }
  return false;
}

containsDuplicate([]); // Edge case: empty array, the loop never runs
containsDuplicate([5, 5]); // Case with a duplicate right at the 2nd element

// Stack using an array
const stack = [];
stack.push('a'); stack.push('b');
stack.pop(); // 'b' (LIFO)

// Queue using an array (shift costs O(n) — know this for interviews!)
const queue = [];
queue.push('a'); queue.push('b');
queue.shift(); // 'a' (FIFO)

stack.pop(); // 'a' — the stack is now empty
stack.pop(); // undefined — edge case: pop() on an empty stack doesn't throw in JS

function bfs(graph, start) {
  const visited = new Set([start]);
  const queue = [start];
  while (queue.length) {
    const node = queue.shift();
    for (const neighbor of graph[node]) {
      if (!visited.has(neighbor)) {
        visited.add(neighbor);
        queue.push(neighbor);
      }
    }
  }
  return visited;
}

function merge(left, right) {
  const res = [];
  while (left.length && right.length) {
    res.push(left[0] <= right[0] ? left.shift() : right.shift());
  }
  return [...res, ...left, ...right];
}

function mergeSort(arr) {
  if (arr.length <= 1) return arr;
  const mid = Math.floor(arr.length / 2);
  return merge(mergeSort(arr.slice(0, mid)), mergeSort(arr.slice(mid)));
}
